float voronoi(vec2 uv) {
    vec2 i = floor(uv);
    vec2 f = fract(uv);
    float minDist1 = 1.0;
    float minDist2 = 1.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = vec2(fract(sin(dot(i + neighbor, vec2(127.1, 311.7))) * 43758.5453));
            vec2 diff = neighbor + point - f;
            float dist = length(diff);
            if (dist < minDist1) {
                minDist2 = minDist1;
                minDist1 = dist;
            } else if (dist < minDist2) {
                minDist2 = dist;
            }
        }
    }
    return minDist2 - minDist1;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    vec3 mainBlue = vec3(0.1, 0.4, 0.6);
    vec3 darkBlue = vec3(0.0, 0.2, 0.4);
    vec3 foamColor = vec3(0.9, 0.9, 0.9);

    float scale1 = 5.0;
    float scale2 = 10.0;
    float distortion1Strength = 0.1;
    float distortion2Strength = 0.15;
    float distortion1Frequency = 5.0;
    float distortion2Frequency = 4.0;
    float distortion1Speed = 2.0;
    float distortion2Speed = 1.5;
    float edge1ThresholdMin = 0.02;
    float edge1ThresholdMax = 0.05;
    float edge2ThresholdMin = 0.03;
    float edge2ThresholdMax = 0.07;

    vec2 uv1 = uv * scale1;
    vec2 uv2 = uv * scale2;

    vec2 distortedUV1 = uv1 + vec2(
        sin(iTime * distortion1Speed + uv1.y * distortion1Frequency) * distortion1Strength,
        cos(iTime * distortion1Speed + uv1.x * distortion1Frequency) * distortion1Strength
    );

    vec2 distortedUV2 = uv2 + vec2(
        cos(iTime * distortion2Speed + uv2.y * distortion2Frequency) * distortion2Strength,
        sin(iTime * distortion2Speed + uv2.x * distortion2Frequency) * distortion2Strength
    );

    float edgeDist1 = voronoi(distortedUV1);
    float edges1 = smoothstep(edge1ThresholdMin, edge1ThresholdMax, edgeDist1);

    float edge1Halo = smoothstep(0.1, 0.5, edgeDist1); // Lighter effect around white lines

    float edgeDist2 = voronoi(distortedUV2);
    float edges2 = smoothstep(edge2ThresholdMin, edge2ThresholdMax, edgeDist2);


    vec3 e = mix(darkBlue, mainBlue, step(0.5, edges2));
    e = mix(foamColor, e, step(0.5, edges1));


    e *= 0.1 + 1.0 - edge1Halo * 0.1; 

    fragColor = vec4(vec3(e), 1.0);
}
